// Keep the strict `pnpm lint` result visible; CI additionally ratchets inherited debt.
// Baseline updates are explicit code-review changes, never generated by this runner.
import { ESLint } from 'eslint';
import { execFileSync } from 'node:child_process';
import { readFile } from 'node:fs/promises';
import { debtFingerprint, admitsDebt } from './eslint-debt-policy.mjs';
import { relative } from 'node:path';
const baseline = JSON.parse(
  await readFile(new URL('./eslint-debt-baseline.json', import.meta.url)),
);
const eslint = new ESLint();
const candidates = execFileSync(
  'git',
  ['ls-files', '--cached', '--others', '--exclude-standard', '-z'],
  { encoding: 'utf8' },
)
  .split('\0')
  .filter((p) => /\.(?:[cm]?[jt]sx?)$/.test(p));
const files = [];
for (const path of candidates) if (!(await eslint.isPathIgnored(path))) files.push(path);
const results = await eslint.lintFiles(files);
const counts = new Map();
let blocked = 0;
let inherited = 0;
for (const result of results) {
  const lines = result.source?.split(/\r?\n/) ?? [];
  for (const m of result.messages.filter((m) => m.severity === 2)) {
    const file = relative(process.cwd(), result.filePath).replaceAll('\\', '/');
    const fingerprint = debtFingerprint(file, m, lines[m.line - 1]);
    const count = (counts.get(fingerprint) ?? 0) + 1;
    counts.set(fingerprint, count);
    if (admitsDebt(baseline, fingerprint, count, m.ruleId)) inherited++;
    else {
      console.error(`${file}:${m.line}:${m.column} ${m.ruleId ?? 'parse'}: ${m.message}`);
      blocked++;
    }
  }
}
console.log(
  `ESLint: ${blocked} unapproved errors; ${inherited} inherited legacy errors (debt, NOT fixed). Strict lint remains available with pnpm lint.`,
);
if (blocked) process.exitCode = 1;
